after.content:
$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $true
$root = Split-Path -Parent $PSScriptRoot
Push-Location $root
try {
  & pwsh -NoProfile -File .\scripts\verify-stage3.ps1
  if ($LASTEXITCODE -ne 0) { throw "Stage 0-3 regression gate failed: $LASTEXITCODE" }
  & .\gradlew.bat :ji-host-core:test :ji-host-sqlite:test :ji-host-web:test `
      :ji-spring-boot-starter:test :ji-remote-bootstrap:test --offline --rerun-tasks --no-daemon
  if ($LASTEXITCODE -ne 0) { throw "Stage 4 Java gate failed: $LASTEXITCODE" }
  & corepack pnpm --offline --filter '@ji/web-app' test
  if ($LASTEXITCODE -ne 0) { throw "Stage 4 Web unit gate failed: $LASTEXITCODE" }
  & corepack pnpm --offline --filter '@ji/web-app' build
  if ($LASTEXITCODE -ne 0) { throw "Stage 4 Web production build failed: $LASTEXITCODE" }
  & corepack pnpm --offline --filter '@ji/web-app' test:e2e
  if ($LASTEXITCODE -ne 0) { throw "Stage 4 browser gate failed: $LASTEXITCODE" }
  & node .\scripts\run-stage4-host-restart.mjs
  if ($LASTEXITCODE -ne 0) { throw "Stage 4 Host restart gate failed: $LASTEXITCODE" }
  & pwsh -NoProfile -File .\scripts\verify-stage4-standalone.ps1
  if ($LASTEXITCODE -ne 0) { throw "Stage 4 standalone gate failed: $LASTEXITCODE" }
} finally {
  Pop-Location
}
